cat > frontend/tests/overview.spec.ts <<'EOF'
import { expect, test } from "@playwright/test";
import { overviewFixture } from "./overview-fixture";
import { parseOverview, loadOverview } from "../src/lib/server/overview";
import { overviewCharts } from "../src/lib/overview";

test("preserves exact amounts beyond Number precision and party identity", () => {
  const fixture = overviewFixture();
  fixture.top_members[0].total.amount = "9007199254740993.123456789";
  fixture.parties[1].party_name = fixture.parties[0].party_name;
  const result = parseOverview(fixture);
  const charts = overviewCharts(result);
  expect(result.topMembers[0].total.amount).toBe("9007199254740993.123456789");
  expect(charts.members[0].value).toBe("£9,007,199,254,740,993.123456789");
  expect(charts.parties).toHaveLength(3);
  expect(charts.parties[2].value).not.toBe("£0.00");
  expect(charts.members.every(bar => Number.isFinite(bar.width))).toBe(true);
});
test("negative party values make pie unavailable without losing values", () => {
  const fixture = overviewFixture(); fixture.parties[0].total.amount = "-1.01";
  const charts = overviewCharts(parseOverview(fixture));
  expect(charts.negativeParty).toBe(true);
  expect(charts.parties[0].value).toBe("−£1.01");
  expect(charts.parties.every(slice => slice.share === 0)).toBe(true);
});
test("zero and all-negative quartiles produce finite geometry", () => {
  for (const amount of ["0", "-123.45"]) {
    const fixture = overviewFixture();
    for (const quartile of fixture.quartiles) quartile.minimum = quartile.maximum = amount;
    for (const member of fixture.top_members) member.total.amount = amount;
    const charts = overviewCharts(parseOverview(fixture));
    expect(charts.quartiles.every(bar => Number.isFinite(bar.y) && Number.isFinite(bar.height))).toBe(true);
    expect(charts.members.every(bar => Number.isFinite(bar.width))).toBe(true);
  }
});
test("rejects malformed coverage and nonempty null ranges", () => {
  const fixture = overviewFixture(); fixture.member_count++;
  expect(() => parseOverview(fixture)).toThrow();
  const nullRange = { ...overviewFixture(), quartiles: overviewFixture().quartiles.map(q => ({...q, minimum: null})) };
  expect(() => parseOverview(nullRange)).toThrow();
});
test("backend failure leaves a usable unavailable state", async () => {
  const fetcher: typeof fetch = async () => new Response("", {status: 503});
  expect(await loadOverview(new AbortController().signal, fetcher, "http://example.test")).toEqual({kind: "unavailable"});
});
EOF
cat > frontend/tests/homepage-charts.spec.ts <<'EOF'
import { expect, test } from "./backend";
import { overviewFixture } from "./overview-fixture";

test("homepage charts render on the server and retain exact values and MP links", async ({ browser, baseURL, backend }) => {
  await backend.route("**/api/overview", route => route.fulfill({json: overviewFixture()}));
  const context = await browser.newContext({javaScriptEnabled: false, baseURL, viewport: { width: 1440, height: 1100 }});
  try {
    const page = await context.newPage();
    await page.goto("/");
    await expect(page.getByRole("heading", {name: "Distribution by quartile"})).toBeVisible();
    await expect(page.getByRole("img", { name: "Declared GBP ranges by rank quartile" })).toBeVisible();
    await expect(page.getByRole("link", {name: "Alex Morgan", exact: true})).toHaveAttribute("href", "/members/1");
    await expect(page.getByText("£150,000.00", {exact: true})).toBeVisible();
    await expect(page.getByText("8 current Commons MPs", {exact: false})).toBeVisible();
    await page.screenshot({path: "/tmp/exposed-homepage-desktop.png", fullPage: true});
    await page.setViewportSize({width: 390, height: 844});
    expect(await page.evaluate(() => document.documentElement.scrollWidth)).toBe(390);
    await page.getByRole("link", {name: "Search MPs and funders"}).click();
    await expect(page.getByRole("searchbox")).toBeVisible();
  } finally { await context.close(); }
});

test("negative and unavailable party totals stay visible", async ({ page, backend }) => {
  const fixture = overviewFixture(); fixture.parties[0].total.amount = "-12.34";
  await backend.route("**/api/overview", route => route.fulfill({json: fixture}));
  await page.goto("/");
  await expect(page.getByText("Pie chart unavailable for negative declared amounts.")).toBeVisible();
  await expect(page.getByText("Labour · −£12.34")).toBeVisible();
});
EOF
